//! Native helpers for Marble Switchyard (std): reading levels.json and the
//! scripted session the parity check runs on both the Rust and TS sims.

use marble_switchyard::sim::{Level, Sim};
use serde::Deserialize;

/// JSON shape of games/marble-switchyard/src/game/levels.json (generated by src/tools/generate.ts).
#[derive(Deserialize, Clone, Debug)]
pub struct LevelJson {
    pub n: u32,
    pub tree: String,
    pub gates: Vec<GateJson>,
    pub cups: Vec<CupJson>,
    pub seq: String,
    pub interval: f64,
    pub speed: f64,
    pub spills: u32,
}

#[derive(Deserialize, Clone, Debug)]
pub struct GateJson {
    pub start: u8,
    #[serde(default)]
    pub auto: bool,
    #[serde(default)]
    pub link: u8,
}

#[derive(Deserialize, Clone, Debug)]
pub struct CupJson {
    pub color: u8,
    pub cap: u8,
}

pub fn to_level(j: &LevelJson) -> Level {
    let mut l = Level::empty();
    l.set_tree(j.tree.as_bytes());
    l.n_gates = j.gates.len();
    for (g, d) in j.gates.iter().enumerate() {
        l.gate_start[g] = d.start;
        l.gate_auto[g] = d.auto as u8;
        l.gate_link[g] = d.link;
    }
    l.n_cups = j.cups.len();
    for (c, d) in j.cups.iter().enumerate() {
        l.cup_color[c] = d.color;
        l.cup_cap[c] = d.cap;
    }
    let seq: Vec<u8> = j.seq.bytes().map(|b| b - b'0').collect();
    l.set_seq(&seq);
    l.interval = j.interval;
    l.speed = j.speed;
    l.spills = j.spills;
    l
}

/// The scripted session (mirrored in games/marble-switchyard/tools/parity.mjs):
/// 3600 frames at 60 fps, a tap every 23 frames on a rotating gate, checksum
/// printed every second.
pub fn trace(l: &Level) -> Vec<String> {
    let mut s = Sim::new(l);
    let mut out = Vec::new();
    for f in 0..3600u32 {
        if f % 23 == 0 && s.n_gates > 0 {
            s.tap(((f / 23) as usize * 5 + 1) % s.n_gates);
        }
        s.update(1.0 / 60.0);
        s.clear_events();
        if f % 60 == 59 {
            out.push(format!("{} {}", f, s.checksum()));
        }
    }
    out
}
